exercises.solution:
def nom_valide(nom):
    return len(nom.strip()) >= 2


def inscrire(nom):
    if not nom_valide(nom):
        return "refusé"
    return "inscrit : " + nom.strip()


def modifier(nom):
    if not nom_valide(nom):
        return "refusé"
    return "modifié : " + nom.strip()

