exercises.solution:
SEUIL_ADMIS = 10
SEUIL_TRES_BIEN = 16


def mention(moyenne):
    if moyenne >= SEUIL_TRES_BIEN:
        return "Très bien"
    if moyenne >= SEUIL_ADMIS:
        return "Admis"
    return "Ajourné"


def admis(moyenne):
    return moyenne >= SEUIL_ADMIS
